function $(n,c){n=n.replace(/^#/,"");const o=/^#?([a-f\d])([a-f\d])([a-f\d])$/i;n=n.replace(o,(a,r,t,u)=>r+r+t+t+u+u);const s=parseInt(n,16),e=s>>16&255,f=s>>8&255,i=s&255;return`${e}, ${f}, ${i}`}function m(n){return`${Math.floor(n/60)<10?`0${Math.floor(n/60)}`:Math.floor(n/60)}:${n%60<10?`0${n%60}`:n%60}`}function d(n){const[c,o]=n.split(":");return Number(c)*60+Number(o)}export{$ as h,d as m,m as s};
